import zlib, bz2, lzma

def _cands(data):
    yield b'\x00' + data
    yield b'\x01' + zlib.compress(data, 9)
    yield b'\x02' + bz2.compress(data, 9)
    f = [{'id': lzma.FILTER_LZMA2, 'preset': 9 | lzma.PRESET_EXTREME, 'lc': 4, 'lp': 0, 'pb': 0}]
    yield b'\x03' + lzma.compress(data, format=lzma.FORMAT_RAW, filters=f)

def compress(data: bytes) -> bytes:
    return min(_cands(data), key=len)

def decompress(blob: bytes) -> bytes:
    t, body = blob[0], blob[1:]
    if t == 0:
        return body
    if t == 1:
        return zlib.decompress(body)
    if t == 2:
        return bz2.decompress(body)
    f = [{'id': lzma.FILTER_LZMA2, 'preset': 9 | lzma.PRESET_EXTREME, 'lc': 4, 'lp': 0, 'pb': 0}]
    return lzma.decompress(body, format=lzma.FORMAT_RAW, filters=f)

